def esc(t):
    t = t.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("'", "\\'").replace('"', '\\"')
    return t.replace("\n", "\\n")

root = os.path.join(os.path.dirname(__file__), "..", "app", "src", "main", "res")
for i, lang in enumerate(LANGS):
    d = os.path.join(root, "values" + ("-" + lang if lang else ""))
    os.makedirs(d, exist_ok=True)
    with open(os.path.join(d, "strings.xml"), "w", encoding="utf-8") as f:
        f.write('<?xml version="1.0" encoding="utf-8"?>\n<!-- Generated by tools/strings.py. Edit the table there. -->\n<resources>\n')
        for k, v in S.items():
            assert len(v) == 7, k
            if i > 0 and k == "app_name":
                continue
            f.write(f'    <string name="{k}">{esc(v[i])}</string>\n')
        f.write("</resources>\n")
print(len(S), "strings x", len(LANGS), "languages")
